// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation as proposer
        bytes32 role = c.PROPOSER_ROLE();
        vm.prank(address(this));
        c.grantRole(role, address(this));

        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), bytes32(0));
        c.schedule(address(this), 0, "", bytes32(0), bytes32(0), 1 days);

        // Cancel the operation
        c.cancel(id);

        // Now check supportsInterface with IAccessControl interface ID
        bytes4 interfaceId = type(IAccessControl).interfaceId;
        bool result = c.supportsInterface(interfaceId);

        // Reference returns true, mutant returns false
        assertTrue(result);
    }
}

// IAccessControl interface is needed for type(IAccessControl).interfaceId
interface IAccessControl {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

