pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Grant EXECUTOR_ROLE to address(1) so we can execute
        bytes32 executorRole = c.EXECUTOR_ROLE();
        c.grantRole(executorRole, address(1));

        // Prepare an operation: target = address(0), value=0, data="", predecessor=0, salt=42
        address target = address(0);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(42));
        uint256 delay = 1;

        // Proposer schedules the operation
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        c.schedule(target, value, data, predecessor, salt, delay);

        // Warp past the delay so operation becomes ready
        vm.warp(block.timestamp + delay + 1);

        // Now address(1) executes the operation (has EXECUTOR_ROLE)
        vm.prank(address(1));
        c.execute{value: 0}(target, value, data, predecessor, salt);

        // Now attempt cancel on the same id – must revert in reference because operation is done
        // (the bug changes supportsInterface but here we just test the revert difference)
        // Wrap cancel in try/catch to observe revert boolean
        bool cancelReverted = false;
        try c.cancel(id) {
            cancelReverted = false;
        } catch {
            cancelReverted = true;
        }

        // The reference: cancel reverts because operation is done (timestamp == _DONE_TIMESTAMP)
        // The bug: cancel may succeed because supportsInterface returns true, but here _afterCall reverts for missing admin role before setting done; still cancel should revert
        // Actually the difference from the given change: supportsInterface returning true does NOT affect cancel revert behavior directly.
        // The provided difference says: supportsInterface(args) completes in both but returns different values.
        // Let's test that: use the id (which is bytes32) – convert to bytes4?
        // supportsInterface takes bytes4; we need a concrete interfaceId.
        // Let's test with interfaceId = 0x01ffc9a7 (ERC165 id) – P returns true, M returns true (both true)
        // With interfaceId = 0x00000001 – P returns false, M returns true -> they diverge.
        bytes4 testId = bytes4(0x00000001);
        bool refSupports = c.supportsInterface(testId); // P returns false
        // Bug would return true, but since we cannot call bug here, we trust the difference.
        // Final assertion: reference supportsInterface returns false for this id
        assertTrue(refSupports == false, "reference should return false");
    }
}

