pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // The bug is in getRoleAdmin returning 0x01 regardless.
        // The cancel function requires onlyRole(PROPOSER_ROLE), which internally calls _checkRole.
        // In the reference, getRoleAdmin(PROPOSER_ROLE) returns TIMELOCK_ADMIN_ROLE (the actual admin).
        // In the mutant, getRoleAdmin(PROPOSER_ROLE) returns bytes32(uint256(1)).
        // We will schedule an operation, then try to cancel it. Cancel uses onlyRole(PROPOSER_ROLE),
        // which gets the admin role via getRoleAdmin. If the admin is wrong, the checkRole call may succeed or fail differently.
        // But we need a scenario where the two diverge observably. The simplest is: 
        // When the caller is a proposer, in the reference, cancel succeeds (because proposer role is checked via its admin),
        // but in the mutant, if getRoleAdmin returns a role that the caller does not have, cancel reverts.
        // However, we need to ensure the buggy getRoleAdmin returns a value that causes a revert for proposer.
        // The buggy getRoleAdmin returns 1. 1 is not the admin role, so in _checkRole(role, account) for PROPOSER_ROLE,
        // it will check if account has role 1 (which they don't) and revert. So cancel will revert in the buggy version.
        // In the reference, cancel will succeed because the proposer has the correct admin role.
        // So we can test: propose an operation, then call cancel as a proposer. Reference succeeds, mutant reverts.

        address proposer = address(this);
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = hex"";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(1));
        uint256 delay = 1 days;

        // Schedule an operation
        c.schedule(target, value, data, predecessor, salt, delay);
        // Warp to make it pending
        vm.warp(block.timestamp + 1 hours);
        // Now try to cancel as the proposer
        // We will use try/catch to see if cancel reverts
        bool success;
        try c.cancel(keccak256(abi.encode(target, value, data, predecessor, salt))) {
            success = true;
        } catch {
            success = false;
        }
        // In reference, cancel should succeed (proposer can cancel). In mutant, cancel reverts.
        // We assert that the behavior matches the reference (success == true) but the bug would make it false.
        // The test passes on reference, fails on mutant.
        assertTrue(success);
    }
}

