pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Grant PROPOSER_ROLE to an attacker
        address attacker = address(0xCAFE);
        bytes32 proposerRole = c.PROPOSER_ROLE();
        c.grantRole(proposerRole, attacker);

        // Schedule an operation as proposer
        vm.prank(attacker);
        c.schedule(address(0xDEAD), 0, hex"", bytes32(0), bytes32(uint256(1)), 1 days);
        bytes32 id = c.hashOperation(address(0xDEAD), 0, hex"", bytes32(0), bytes32(uint256(1)));

        // Warp past the delay so operation is pending
        vm.warp(block.timestamp + 1 days + 1);

        // Attacker tries to cancel; should revert but buggy version allows it
        bool ok = true;
        vm.prank(attacker);
        try c.cancel(id) { ok = true; } catch { ok = false; }

        // In reference: cancel() reverts because onlyRole(PROPOSER_ROLE) calls _checkRole with admin = getRoleAdmin(PROPOSER_ROLE) = DEFAULT_ADMIN_ROLE (0x00)
        // which the attacker does not have => revert => ok = false.
        // In bug: getRoleAdmin returns 0x01, so the check passes => cancel succeeds => ok = true.
        assertTrue(ok == false);
    }
}

