import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Setup: create target, value, data, predecessor, salt for a schedule
        address target = address(0x123);
        uint256 value = 0;
        bytes memory data = hex"";
        bytes32 predecessor = bytes32(uint256(0));
        bytes32 salt = bytes32(uint256(0x789));
        uint256 delay = 2;

        // Schedule a pending operation as proposer (this contract has PROPOSER_ROLE via deployment)
        c.schedule(target, value, data, predecessor, salt, delay);

        // Compute the operation id
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Verify it is scheduled (pending)
        assertTrue(c.isOperationPending(id));

        // Now cancel as an account with TIMELOCK_ADMIN_ROLE (this contract has it via deployment)
        // In reference: getRoleAdmin(PROPOSER_ROLE) == TIMELOCK_ADMIN_ROLE (0x00), so onlyRole(0x00) passes
        // In bug: getRoleAdmin(PROPOSER_ROLE) == 0x01, so onlyRole(0x01) checks if caller has role 0x01, which it does not -> revert
        c.cancel(id);

        // After cancel, operation should be done (timestamp deleted? actually cancel deletes the timestamp, so it becomes 0, which is not > 1, so isOperationDone returns false, isOperationPending returns false)
        // We assert that operation is no longer pending (i.e., timestamp is 0) — in reference it is, in bug the call reverts before deletion
        // However if the call reverts, the assertion wouldn't be reached. To handle safely, we use try/catch.
        // Actually we can check the timestamp directly via getTimestamp
        assertTrue(!c.isOperationPending(id));
    }
}

