        vm.warp(block.timestamp + 1);

        // Now proposer2 tries to cancel the operation
        // In reference: getRoleAdmin(PROPOSER_ROLE) returns TIMELOCK_ADMIN_ROLE, so onlyRole checks for TIMELOCK_ADMIN_ROLE -> proposer2 doesn't have it -> revert
