contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Setup: give a proposer role to address(1) and schedule an operation
        vm.prank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), address(1));

        // address(1) schedules an operation
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0x1234);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        vm.prank(address(1));
        c.schedule(target, value, data, predecessor, salt, 100);

        // Now address(2) tries to cancel the operation
        // In the reference, this will revert because address(2) is not a proposer
        // In the buggy version, address(2) can first renounce the proposer role from address(1)
        // then become the only proposer via the broken renounceRole logic
        // But the actual test: just try to cancel from a non-proposer

        bool ok;
        vm.prank(address(2));
        try c.cancel(id) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference, ok is false (revert)
        // In the buggy version, ok is true (cancel succeeds because the bug enables role manipulation)
        // Actually the bug is in renounceRole - but cancel doesn't use renounceRole directly.
        // The difference described is about renounceRole state variable, but there is no public getter for it.
        // To observe a difference, we need to use the public surface.
        // Let's try a different approach: observe that in buggy version, a non-admin can renounce roles for others.

        // Reset scenario: check that a non-account can renounce someone else's role
        vm.prank(address(2));
        c.renounceRole(c.PROPOSER_ROLE(), address(1));

        // In reference, the renounceRole would have reverted (require account == msg.sender fails)
        // In buggy, it succeeds, meaning address(1) loses PROPOSER_ROLE
        bool hasRole = c.hasRole(c.PROPOSER_ROLE(), address(1));

        // Reference: hasRole is true (renounceRole reverted)
        // Buggy: hasRole is false (renounceRole succeeded)
        assertTrue(!hasRole, "Bug: non-self renounce succeeded");
    }
}

