    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation
        bytes32 id = c.hashOperation(address(0), 0, "", bytes32(0), bytes32(0));
        c.schedule(address(0), 0, "", bytes32(0), bytes32(0), 1 days);
        // Warp past the delay so the operation becomes ready
        vm.warp(block.timestamp + 1 days);
        // Execute the operation to make it done
        c.execute(address(0), 0, "", bytes32(0), bytes32(0));
        // Now the operation is done (isOperationPending returns false)
        // Try to cancel with the same id – reference reverts, buggy does not
        bool ok;
        try c.cancel(id) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: cancel reverts → ok = false
        // Buggy: cancel succeeds → ok = true
        assertTrue(!ok, "cancel should revert on non-pending operation");
    }
}

