pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation
        bytes32 id = c.hashOperation(address(0xdead), 0, hex"42", bytes32(0), bytes32(uint256(1)));
        c.schedule(address(0xdead), 0, hex"42", bytes32(0), bytes32(uint256(1)), 3600);
        // Cancel it
        c.cancel(id);
        // Reschedule the same operation
        c.schedule(address(0xdead), 0, hex"42", bytes32(0), bytes32(uint256(1)), 3600);
        // In reference, cancel sets timestamp to 0, so rescheduling should fail (require(!isOperation(id)) would revert)
        // But in buggy version, require(true) always passes, so rescheduling succeeds
        // However, the buggy version's schedule will revert with "TimelockController: insufficient delay" if delay < getMinDelay()? No, delay = 3600 >= 0.
        // Actually both will succeed in schedule (since buggy always passes require(true) instead of checking isOperation).
        // The difference: after second schedule, in reference, the timestamp was set again (since first schedule's timestamp was deleted by cancel, so isOperation returns false, so schedule proceeds).
        // Wait, reference also allows rescheduling after cancel because cancel deletes timestamp, so isOperation returns false. So both allow.
        // Need a difference: The buggy _schedule with require(true) never reverts, but reference _schedule reverts if !isOperation(id) is false after cancel. After cancel, isOperation(id) returns false (timestamp deleted), so !isOperation(id) is true, so require passes. So both allow rescheduling.
        // Re-evaluate: The mutant replaces !isOperation(id) with true. In reference, after scheduling and cancel, isOperation returns false, so require(!isOperation(id)) passes. In buggy, require(true) also passes. So no divergence in this sequence.
        // To cause divergence: schedule, cancel, then try to schedule again. In reference, it succeeds. In buggy, it also succeeds. Not different.
        // Instead, consider: schedule the same operation twice without cancel. In reference, the second schedule reverts (require(!isOperation(id)) fails because isOperation returns true). In buggy, require(true) passes, so second schedule succeeds, overwriting timestamp. So after two schedules, the timestamp in buggy is the later one, while in reference it remains the first (since second reverts). But we need to observe difference through public getter. So schedule once, then try to schedule same id again. In reference, it reverts; in buggy, it succeeds and timestamp changes. We can check that after the second schedule attempt, the timestamp differs: in reference, timestamp is from first schedule; in buggy, timestamp from second schedule (different due to block.timestamp change). Use vm.warp to ensure different timestamps.
        vm.warp(1000);
        bytes32 id2 = c.hashOperation(address(0xdead), 0, hex"42", bytes32(0), bytes32(uint256(1)));
        c.schedule(address(0xdead), 0, hex"42", bytes32(0), bytes32(uint256(1)), 3600); // first schedule, timestamp = 1000 + 3600 = 4600
        vm.warp(2000);
        // Try second schedule of same id
        try c.schedule(address(0xdead), 0, hex"42", bytes32(0), bytes32(uint256(1)), 3600) {
            // buggy: succeeds, timestamp = 2000 + 3600 = 5600
        } catch {
            // reference: reverts, timestamp remains 4600
        }
        // Now get timestamp
        uint256 ts = c.getTimestamp(id2);
        // In reference, ts == 4600; in buggy, ts == 5600
        assertTrue(ts == 4600, "Expected timestamp from first schedule");
    }
}

